fn enc_response_metadata(out: &mut Vec<u8>, v: &ResponseMetadata, depth: i32) {
    out.push(b'{');
    let mut first = true;
    if !v.code.is_empty() {
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "code");
        out.extend_from_slice(b": ");
        esc(out, &v.code);
    }
    if !v.error.is_empty() {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "error");
        out.extend_from_slice(b": ");
        esc(out, &v.error);
    }
    if let Some(value) = &v.answer {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "answer");
        out.extend_from_slice(b": ");
        enc_answer(out, value, depth + 1);
    }
    if !v.records.is_empty() {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "records");
        out.extend_from_slice(b": ");
        enc_list(out, &v.records, depth + 1, enc_record_metadata);
    }
    if !first {
        out.push(b'\n');
        pad(out, depth);
    }
    out.push(b'}');
}

